using GridRegion=OpenSim.Services.Interfaces.GridRegion;
using System;using System.Text;using System.Collections.Specialized;using OpenMetaverse;using OpenMetaverse.StructuredData;using OpenSim.Framework;using OpenSim.Services.Interfaces;using OpenSim.Framework.Servers.HttpServer;using OpenSim.Server.Handlers.Simulation;
namespace log4net{public interface ILog{void InfoFormat(string s,params object[] args);void DebugFormat(string s,params object[] args);}public static class LogManager{class Log:ILog{public void InfoFormat(string s,params object[] args){}public void DebugFormat(string s,params object[] args){}}public static ILog GetLogger(Type t)=>new Log();}}
namespace OpenSim.Framework{public interface IScene{ISceneObject DeserializeObject(string xml);bool AllowScriptCrossings{get;}}public interface ISceneObject{void ExtraFromXmlString(string s);bool HasGroupChanged{set;}void SetState(string s,IScene scene);}public static class Util{public static Encoding UTF8=Encoding.UTF8;}}
namespace OpenSim.Services.Interfaces{public class GridRegion{public UUID RegionID;public int RegionLocX,RegionLocY;public string RegionName;}public interface ISimulationService{IScene GetScene(UUID id);bool CreateObject(GridRegion d,Vector3 p,ISceneObject o,bool local);}}
namespace OpenSim.Framework.Servers.HttpServer{public class IOSHttpRequest{public string HttpMethod,Body;public NameValueCollection Headers=new();}public class IOSHttpResponse{public bool KeepAlive=true;public int StatusCode=211;public byte[] RawBuffer=Encoding.UTF8.GetBytes("before");public string ContentType="before-type";}public abstract class SimpleStreamHandler{protected SimpleStreamHandler(string path){}protected abstract void ProcessRequest(IOSHttpRequest request,IOSHttpResponse response);}}
namespace OpenSim.Server.Handlers.Simulation{public static class Utils{public static byte[] falseStrBytes=Encoding.UTF8.GetBytes("false");public static OSDMap DeserializeJSONOSMap(IOSHttpRequest request){try{return OSDParser.DeserializeJson(request.Body) as OSDMap;}catch{return null;}}}}
class ObjectReference{
public class Context{public OSDMap command;public string trace="";public void Log(string op,string value=""){trace+=op+":"+H(value)+";";if(command["failure"].AsString()==op)throw new Exception();}}
class Obj:ISceneObject{Context ctx;public Obj(Context c){ctx=c;}public void ExtraFromXmlString(string s)=>ctx.Log("extra",s);public bool HasGroupChanged{set=>ctx.Log("modified",value?"1":"0");}public void SetState(string s,IScene scene)=>ctx.Log("state",s);}
class Scene:IScene{Context ctx;public Scene(Context c){ctx=c;}public ISceneObject DeserializeObject(string s){ctx.Log("deserialize",s);return ctx.command["null_object"].AsBoolean()?null:new Obj(ctx);}public bool AllowScriptCrossings{get{ctx.Log("allow");return ctx.command["allow"].AsBoolean();}}}
class Service:ISimulationService{Context ctx;public Service(Context c){ctx=c;}public IScene GetScene(UUID id){ctx.Log("scene",id.ToString());return ctx.command["null_scene"].AsBoolean()?null:new Scene(ctx);}public bool CreateObject(GridRegion d,Vector3 p,ISceneObject o,bool local){ctx.Log("create",d.RegionID+":"+d.RegionLocX+":"+d.RegionLocY+":"+d.RegionName+":"+p+":"+(local?"1":"0"));return !ctx.command["deny"].AsBoolean();}}
class Handler:ObjectSimpleHandler{public Handler(ISimulationService s):base(s){}public void Process(IOSHttpRequest r,IOSHttpResponse s)=>ProcessRequest(r,s);public void Post(OSDMap a,IOSHttpResponse s)=>DoObjectPost(a,s);}
class Over:Handler{Context ctx;public Over(ISimulationService s,Context c):base(s){ctx=c;}protected override bool CreateObject(GridRegion d,Vector3 p,ISceneObject o){ctx.Log("override",d.RegionID+":"+p);return !ctx.command["deny"].AsBoolean();}}
static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();public static void Main(){System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var ctx=new Context{command=(OSDMap)OSDParser.DeserializeJson(Encoding.UTF8.GetString(Convert.FromHexString(line)))};ISimulationService service=ctx.command["null_service"].AsBoolean()?null:new Service(ctx);Handler handler=ctx.command["override"].AsBoolean()?new Over(service,ctx):new Handler(service);var response=new IOSHttpResponse();bool failed=false;try{if(ctx.command["core"].AsBoolean())handler.Post((OSDMap)ctx.command["args"],response);else{var request=new IOSHttpRequest{HttpMethod=ctx.command["method"].AsString(),Body=ctx.command.ContainsKey("body")?ctx.command["body"].AsString():OSDParser.SerializeJsonString(ctx.command["args"],true)};if(ctx.command["shard"].AsBoolean())request.Headers["x-secondlife-shard"]="";handler.Process(request,response);}}catch{failed=true;}Console.WriteLine((failed?1:0)+"|"+response.StatusCode+"|"+(response.KeepAlive?1:0)+"|"+H(Encoding.UTF8.GetString(response.RawBuffer))+"|"+H(response.ContentType)+"|"+H(ctx.trace));}}}
